// Find the PR for the issue: branch claude/issue-<N>-…, a linked issue, or "Closes #N" in the text
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const metas = $('Wait').all().map(i => i.json);
return $input.all().map((it, idx) => {
  const m = metas[idx];
  const n = m.issue_number;
  const since = new Date(m.started_at).getTime() - 5 * 60e3;
  const closes = new RegExp(`(close[sd]?|fix(e[sd])?|resolve[sd]?)\\s+#${n}\\b`, 'i');
  const branch = new RegExp(`^claude/issue-${n}(\\D|$)`);
  const prs = it.json.data?.repository?.pullRequests?.nodes;
  const head = `${esc(m.repo)}#${n}: ${esc(m.title)}`;
  const session = `<a href="${m.session_url}">Open session</a>`;
  if (!prs) return { json: { text: `⚠️ PR check for ${head} failed (GitHub unreachable).\n${session}` } };
  const pr = prs.find(p => new Date(p.createdAt).getTime() >= since && (
    branch.test(p.headRefName || '') ||
    (p.closingIssuesReferences?.nodes || []).some(x => x.number === n) ||
    closes.test(p.body || '')));
  if (!pr) return { json: { text: `⚠️ No PR for ${head}\nAfter 90 minutes there is no matching pull request.\n${session}` } };
  const state = pr.state === 'MERGED' ? 'merged' : pr.state === 'CLOSED' ? 'closed' : pr.isDraft ? 'draft, not finished yet' : 'ready for review';
  const gaps = String(pr.body || '').split(/\n(?=#{1,6}\s)/).find(s => /^#{1,6}\s*Gaps in the issue/i.test(s));
  const gapText = gaps ? gaps.replace(/^#{1,6}[^\n]*\n?/, '').trim().slice(0, 600) : '';
  return { json: { text: [
    `${pr.isDraft ? '📝' : '✅'} PR for ${head}`,
    `Status: ${state}`,
    `<a href="${pr.url}">PR #${pr.number}: ${esc(pr.title)}</a>`,
    gapText && !/^(none|-|–)\.?$/i.test(gapText) ? `\nGaps in the issue:\n${esc(gapText)}` : null,
  ].filter(Boolean).join('\n') } };
});
